package ru.metro.objmodels.network;
import io.netty.buffer.ByteBuf;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.util.math.BlockPos;import net.minecraftforge.fml.common.network.simpleimpl.*;import ru.metro.objmodels.common.*;
public class PlaceModelMessage implements IMessage {String model="";int rotation;public PlaceModelMessage(){}public PlaceModelMessage(String m,int r){model=m;rotation=r;}public void fromBytes(ByteBuf b){model=read(b);rotation=b.readInt();}public void toBytes(ByteBuf b){write(b,model);b.writeInt(rotation);}static void write(ByteBuf b,String s){byte[]a=s.getBytes(java.nio.charset.StandardCharsets.UTF_8);b.writeShort(a.length);b.writeBytes(a);}static String read(ByteBuf b){byte[]a=new byte[b.readUnsignedShort()];b.readBytes(a);return new String(a,java.nio.charset.StandardCharsets.UTF_8);}
 public static class Handler implements IMessageHandler<PlaceModelMessage,IMessage>{public IMessage onMessage(PlaceModelMessage m,MessageContext c){EntityPlayerMP p=c.getServerHandler().player;net.minecraft.util.IThreadListener thread=p.getServerWorld();thread.addScheduledTask(()->{if(m.model.length()>128||!ObjModelsRegistry.names().contains(m.model)||p.getDistanceSq(p.getPosition())>100)return;BlockPos pos=p.getPosition().offset(p.getHorizontalFacing());PlacedModelEntity e=new PlacedModelEntity(p.world,pos.getX()+.5,pos.getY(),pos.getZ()+.5,m.model,m.rotation);p.world.spawnEntity(e);});return null;}}
}
